action.mutation:
mutation CreatePackagingMaterial($payload: [PackagingMaterialCreatePayloadInput!]!) {
  mutation: createPackagingMaterial(payload: $payload) { 
    id
    code
  }
}

mutation UpdatePackagingMaterial($payload: [PackagingMaterialUpdatePayloadInput!]!) {
  mutation: updatePackagingMaterial(payload: $payload) { 
    id
    code
  }
}

mutation DeletePackagingMaterial($payload: [PackagingMaterialDeletePayloadInput!]!) {
  mutation: deletePackagingMaterial(payload: $payload) { 
    id
    code
  }
}
